//! The engine's block template: the compiled interface of the shader library a
//! section is built against.
//!
//! This is not derivable from a declaration - a generated minimal block fails at
//! shader load - so it is the one **engine constant** of the section's device
//! preamble. A generated preamble is this template with the header's three
//! varying words and the channel stream rewritten (see [super::shader_block]),
//! which is why the engine data file no longer carries it.
//!
//! Parsed: 120-byte header ({version 1, groups 36, cbuffers 2, records+8}),
//! the config record table, then the channel stream.

/// The template as hex.
pub const BLOCK_TEMPLATE: &str = "";

/// The template bytes.
pub fn engine_block() -> Vec<u8> {
    BLOCK_TEMPLATE
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| {
            u8::from_str_radix(std::str::from_utf8(pair).expect("ascii"), 16).expect("hex")
        })
        .collect()
}